for args in sources: fetch(*args)
for key,q in [('ircc_study_ad_hoc','Study Permit Holders Ad Hoc'),('ircc_study_processing','study permit applications'),('pal_catalogue','provincial attestation')]:
    url='https://open.canada.ca/data/api/action/package_search?'+urllib.parse.urlencode({'q':q,'rows':50})
    p=fetch(key,url,'raw/metadata/'+key+'.json','Open Canada catalogue search: '+q,'catalogue_search','Search evidence; not a dataset of student counts.')
    if p:
        result=json.loads(p.read_text(encoding='utf-8'))['result']
        print('CATALOGUE',key,result['count'])
        for r in result['results'][:15]: print(r['id'],r.get('title'),flush=True)
